  ('f505b1de-df93-40ea-96d6-2c3fa1556e1f', 'a2b3c4d5-7e8f-4a52-9b12-2c3d4e5f6a22', '4e153b3d-62a2-427c-ab46-7b5ece37c129', 'subtopic'::public.curated_course_node_type, 'Population aging and longevity', 'Students learn why aging is a central social-work issue: longer lives reshape families, labor markets, health systems, housing, and public budgets.', 0),
