  ('f63900a2-7c65-4fea-ab70-aa10acf9777c', 'a2b3c4d5-7e8f-4a52-9b12-2c3d4e5f6a22', 'bca8f1ac-3599-454b-b4cd-983b569a9099', 'concept'::public.curated_course_node_type, 'Monitoring, follow-up, and outcome tracking', null, 2),
