select
  'aging-gerontological-social-work',
  null,
  'Aging / Gerontological Social Work',
  'Aging / Gerontological Social Work',
  'Aging / Gerontological Social Work prepares students to practice with older adults, caregivers, families, organizations, and communities in a rapidly aging society. Students learn aging demographics, life-course development, physical and cognitive aging, psychosocial aging, caregiving, long-term services, elder mistreatment, end-of-life care, aging policy, diversity, and evidence-informed social work practice. The course emphasizes person-in-environment assessment, dignity, autonomy, cultural humility, anti-oppressive practice, interprofessional care, and practical navigation of aging-service systems.',
  $agswjson${"slug": "aging-gerontological-social-work", "title": "Aging / Gerontological Social Work", "description": "Aging / Gerontological Social Work prepares students to practice with older adults, caregivers, families, organizations, and communities in a rapidly aging society. Students learn aging demographics, life-course development, physical and cognitive aging, psychosocial aging, caregiving, long-term services, elder mistreatment, end-of-life care, aging policy, diversity, and evidence-informed social work practice. The course emphasizes person-in-environment assessment, dignity, autonomy, cultural humility, anti-oppressive practice, interprofessional care, and practical navigation of aging-service systems.", "topics": [{"id": "4e153b3d-62a2-427c-ab46-7b5ece37c129", "type": "topic", "title": "Demographics, Longevity, and the Aging Society", "description": "This opening section gives students the map of aging: who is aging, where, under what social conditions, and why those patterns matter for social work practice and policy.", "children": [{"id": "f505b1de-df93-40ea-96d6-2c3fa1556e1f", "type": "subtopic", "title": "Population aging and longevity", "children": [{"id": "de957a3e-c27a-4a0f-a4a8-ce6c3b4f2e97", "type": "concept", "title": "Age pyramids and dependency ratios"}, {"id": "46357cde-6fa4-460f-a78d-14637ff2d335", "type": "concept", "title": "Life expectancy, health expectancy, and compression of morbidity"}, {"id": "474fd8af-3531-42c2-bf41-671212483461", "type": "concept", "title": "Global, national, state, and local aging trends"}], "description": "Students learn why aging is a central social-work issue: longer lives reshape families, labor markets, health systems, housing, and public budgets."}, {"id": "e426a7eb-2c96-426d-ab73-06901ad1bb89", "type": "subtopic", "title": "Social determinants of aging", "children": [{"id": "e8c20a7e-6eb7-44c9-afc8-648a0e9718c6", "type": "concept", "title": "Cumulative advantage and disadvantage"}, {"id": "a5b53929-3a82-4d43-8275-424a8e7a69ad", "type": "concept", "title": "Place, environment, and age-friendly communities"}, {"id": "a701fe61-8408-4fdc-95cb-99d33cf23769", "type": "concept", "title": "Poverty, wealth, work history, and retirement security"}], "description": "This subtopic links older-adult outcomes to housing, income, racism, neighborhood conditions, food access, transportation, and social connection."}, {"id": "991cfa1d-1ade-45a8-8150-f2b13623e192", "type": "subtopic", "title": "Ageism and the social construction of later life", "children": [{"id": "0ccdb46e-09e5-4670-937f-22f98d39778f", "type": "concept", "title": "Implicit and explicit ageism"}, {"id": "b6cdd6a9-eb2b-4394-8835-74b6af719882", "type": "concept", "title": "Language and representation"}, {"id": "49c7a377-2d2b-4895-8450-c27b944260dc", "type": "concept", "title": "Anti-ageist practice and advocacy"}], "description": "Students examine how stereotypes shape practice, policy, employment, health care, media, and older adults' self-understanding."}]}, {"id": "97c60dfa-3ac5-46ab-9281-b082ce7e8643", "type": "topic", "title": "Theories of Aging, Life Course, and Person-in-Environment Practice", "description": "This section gives students the conceptual language to understand later life through development, environment, identity, social structure, and lived experience.", "children": [{"id": "cd09256d-cec3-4820-ae68-f6606860b409", "type": "subtopic", "title": "Life-course and ecological frameworks", "children": [{"id": "98512dc6-67d4-46c6-bd90-23cea0a470ea", "type": "concept", "title": "Person-in-environment assessment"}, {"id": "bfcde410-1a21-42ad-8795-d665703262e0", "type": "concept", "title": "Life-course transitions and turning points"}, {"id": "108960bf-0405-48ae-b2b4-510d7898f058", "type": "concept", "title": "Ecological systems across micro, mezzo, and macro levels"}], "description": "The point is to see aging as a developmental, relational, cultural, and structural process rather than a purely individual condition."}, {"id": "9d6fea8d-b81b-465d-9357-fa898a5dea44", "type": "subtopic", "title": "Theories of aging", "children": [{"id": "988d7241-61d9-4e36-9b59-11b40afff451", "type": "concept", "title": "Continuity, activity, disengagement, and modernization theories"}, {"id": "b037584c-2cd0-43d5-9a27-4713157607f5", "type": "concept", "title": "Selective optimization with compensation"}, {"id": "2b4487d4-dadf-4656-badb-733a5b07007f", "type": "concept", "title": "Critical gerontology and political economy of aging"}], "description": "Theory helps students interpret adaptation, continuity, loss, role change, wisdom, disengagement, activity, and successful aging without reducing clients to one model."}, {"id": "5126293d-93cb-45bf-b59e-36b6ad6cc943", "type": "subtopic", "title": "Strengths and resilience perspectives", "children": [{"id": "71eaa661-7568-4e31-9635-8e9f8047496e", "type": "concept", "title": "Narrative and life review"}, {"id": "0adfa24d-2a90-4ebf-bf96-71591cc9128c", "type": "concept", "title": "Resilience under adversity"}, {"id": "491861f0-10dc-4373-8270-20db288fafd7", "type": "concept", "title": "Protective factors and community assets"}], "description": "Students learn to identify capacities, relationships, meaning, and cultural resources alongside risk and need."}]}, {"id": "8496743b-2538-4b9b-9cde-a1121a957d3b", "type": "topic", "title": "Physical Aging, Functional Ability, Frailty, and Chronic Conditions", "description": "This section builds practice literacy around physical aging, function, disability, frailty, and chronic illness without reducing older adults to diagnoses.", "children": [{"id": "9657debb-b47a-4142-aca7-850ce6c3c977", "type": "subtopic", "title": "Normal aging and functional change", "children": [{"id": "22639735-159c-4aaa-82dd-620ca2dd41de", "type": "concept", "title": "Sensory change, mobility, sleep, nutrition, and pain"}, {"id": "9bb5c80f-3af4-4e3d-97a1-bb82be12f7a2", "type": "concept", "title": "Activities of daily living and instrumental activities"}, {"id": "f693789a-16fd-4d74-83ba-0a1258d3c459", "type": "concept", "title": "Universal design and environmental fit"}], "description": "Students distinguish expected physical aging from disease, disability, neglect, and remediable environmental barriers."}, {"id": "1f1c56d7-c0b8-4c0b-b3cc-fdf7715db2a5", "type": "subtopic", "title": "Frailty, falls, and geriatric syndromes", "children": [{"id": "3c60f9ed-9095-472f-8333-d84eaaa0872f", "type": "concept", "title": "Frailty phenotype and cumulative deficit models"}, {"id": "9a9088b9-e0d5-4c7d-9f10-c7259167466f", "type": "concept", "title": "Falls risk and mobility supports"}, {"id": "db016a88-772b-4b91-9a7c-2e0bca8063ff", "type": "concept", "title": "Incontinence, pressure injuries, and malnutrition"}], "description": "This material prepares students to spot high-risk patterns that require coordinated assessment, prevention, and referral."}, {"id": "9ab5700c-fec9-49d9-b7d3-a94de225828a", "type": "subtopic", "title": "Chronic illness and multimorbidity", "children": [{"id": "467dcc1b-18e7-4790-a236-7d1d14094b37", "type": "concept", "title": "Diabetes, cardiovascular disease, COPD, arthritis, osteoporosis"}, {"id": "dd829ab1-f36a-48a8-b69c-f79d02b15d60", "type": "concept", "title": "Self-management and health literacy"}, {"id": "cef7ae77-fa4c-4700-abe1-e1c769c20444", "type": "concept", "title": "Medication burden and deprescribing conversations"}], "description": "Students learn how multiple conditions interact with poverty, caregiving, adherence, disability, and care fragmentation."}]}, {"id": "f173f4ba-46e1-4c09-83dd-acbe83d17629", "type": "topic", "title": "Cognitive Aging, Dementia, Delirium, and Mental Health", "description": "This section prepares students to address cognition and mental health with accuracy, humility, and practical referral awareness.", "children": [{"id": "bb5b80f7-16f6-486b-a384-c759bef62059", "type": "subtopic", "title": "Cognitive aging and screening", "children": [{"id": "bbfa3248-7c6f-4fbb-8983-528dd49a3ec5", "type": "concept", "title": "Normal cognitive aging"}, {"id": "56ceba11-7ab1-4621-8f72-66ddff391d04", "type": "concept", "title": "Mild cognitive impairment"}, {"id": "f9c58254-0bf2-4daf-8780-3d37a8482b23", "type": "concept", "title": "Screening tools and referral pathways"}], "description": "Students learn to discuss memory and cognition respectfully, screen appropriately, and recognize when specialized evaluation is needed."}, {"id": "dcde475e-eda9-4d16-aa28-bdc504d7d9fa", "type": "subtopic", "title": "Dementia, delirium, and decision-making", "children": [{"id": "cf430a14-9ac0-4318-bcc0-bf06d6ef0e71", "type": "concept", "title": "Alzheimer's disease and related dementias"}, {"id": "d90005bf-cc5d-4805-8411-91231cc7bb50", "type": "concept", "title": "Delirium warning signs"}, {"id": "20d75a46-4c53-42ec-9472-42ee73be4058", "type": "concept", "title": "Supported decision-making and capacity questions"}], "description": "This subtopic teaches students to differentiate chronic cognitive decline from acute confusion and to support safety without erasing autonomy."}, {"id": "2723c050-6c84-4ce8-aa41-666d81354836", "type": "subtopic", "title": "Mental health and substance use in later life", "children": [{"id": "c057cfcb-f473-492e-8a53-07ba795bd83f", "type": "concept", "title": "Depression, anxiety, grief, trauma, and suicide risk"}, {"id": "eb60f761-2d94-47aa-a648-2c1bcb0a230a", "type": "concept", "title": "Alcohol, medication, and substance-use concerns"}, {"id": "62d7c987-9a54-471b-935e-7208bd768424", "type": "concept", "title": "Integrated behavioral health and referral"}], "description": "Students practice recognizing underdiagnosed distress and risk among older adults."}]}, {"id": "7863ebb0-1f13-46d1-aa29-54c23847c51f", "type": "topic", "title": "Psychosocial Aging, Identity, Meaning, Grief, and Resilience", "description": "This section centers the emotional, relational, cultural, and existential dimensions of later life.", "children": [{"id": "cdf3f7b8-0eae-4cd1-ab20-d774a16c4434", "type": "subtopic", "title": "Identity, roles, and meaning", "children": [{"id": "f0e28f9a-951b-402e-ad70-405530e69e36", "type": "concept", "title": "Retirement and work identity"}, {"id": "09cb9d4a-480b-476c-8068-7698b1573902", "type": "concept", "title": "Grandparenting, friendship, intimacy, and sexuality"}, {"id": "560ea276-7183-4b7a-8676-f3210d862943", "type": "concept", "title": "Spirituality, meaning, and life review"}], "description": "Later life often brings role transitions, but also creativity, contribution, sexuality, spirituality, and renewed purpose."}, {"id": "aea35c8a-0bfd-4437-a81f-c33db136db19", "type": "subtopic", "title": "Social isolation and loneliness", "children": [{"id": "444c810f-d97e-469d-819e-31202e863a86", "type": "concept", "title": "Risk and protective factors"}, {"id": "08ab18b3-4971-4ace-b8d1-c50d3487721c", "type": "concept", "title": "Community connection and mutual aid"}, {"id": "f43d23c4-ca53-4ceb-a729-9bcdbe0047b1", "type": "concept", "title": "Technology-mediated connection and its limits"}], "description": "Students learn why isolation is both a clinical and public-health issue and how to intervene beyond generic referral lists."}, {"id": "b8c49639-db05-46c0-aa07-61153c677c14", "type": "subtopic", "title": "Loss, grief, and resilience", "children": [{"id": "ba1535b7-5df6-4914-a9f8-a3c705fe9426", "type": "concept", "title": "Complicated grief and trauma histories"}, {"id": "d6a61a64-df97-4e9d-8fb2-455c6f0a524f", "type": "concept", "title": "Ambiguous loss in dementia and caregiving"}, {"id": "9adb2975-b34e-49f1-a101-ab86672fce19", "type": "concept", "title": "Resilience practices and culturally grounded mourning"}], "description": "This subtopic equips students to work with bereavement, ambiguous loss, disability-related loss, and accumulated life transitions."}]}, {"id": "5d46869c-95b5-4f48-909d-cb6c8e5ed3b2", "type": "topic", "title": "Assessment, Engagement, and Evidence-Informed Practice with Older Adults", "description": "This section turns course knowledge into practice skill by teaching students how to assess, engage, plan, and evaluate with older adults.", "children": [{"id": "d4091bec-6ff7-48ee-8b5d-65ff27045d39", "type": "subtopic", "title": "Comprehensive gerontological assessment", "children": [{"id": "486c39c5-ca0a-4f40-b948-18ab96f138fd", "type": "concept", "title": "Presenting concern, strengths, and goals"}, {"id": "9ceef5b9-1064-4286-99ae-d11cc8b14ca6", "type": "concept", "title": "ADLs, IADLs, cognition, mood, safety, and social supports"}, {"id": "673f6bcc-8f65-4705-9789-b81b1a28274d", "type": "concept", "title": "Housing, benefits, transportation, and legal needs"}], "description": "Students learn to synthesize biopsychosocial-spiritual, functional, cognitive, environmental, cultural, and financial information."}, {"id": "1eb8a456-6878-45d4-851f-4e958a245344", "type": "subtopic", "title": "Engagement and interviewing", "children": [{"id": "a15fa4cb-c388-41ec-86b5-cb4b3a513cb9", "type": "concept", "title": "Motivational interviewing and shared decision-making"}, {"id": "9c9ed2fe-1164-4203-8292-204f34dc585b", "type": "concept", "title": "Communication adaptations"}, {"id": "76a1f040-1290-4213-ad29-858cf14863dc", "type": "concept", "title": "Working with interpreters and family participants"}], "description": "The aim is to build trust while adapting to hearing, vision, cognition, trauma histories, culture, and family dynamics."}, {"id": "bca8f1ac-3599-454b-b4cd-983b569a9099", "type": "subtopic", "title": "Evidence-informed intervention planning", "children": [{"id": "386b2f2b-d656-46ca-afcd-2a420e695c4e", "type": "concept", "title": "SMART goals and service plans"}, {"id": "ab468e1f-c50c-4b91-b2b4-fa705e92b1c0", "type": "concept", "title": "Brief interventions and referrals"}, {"id": "f63900a2-7c65-4fea-ab70-aa10acf9777c", "type": "concept", "title": "Monitoring, follow-up, and outcome tracking"}], "description": "Students connect assessment findings to interventions that are realistic, ethical, measurable, and person-centered."}]}, {"id": "a471f005-9873-44bc-8ac5-d4e7277afbb7", "type": "topic", "title": "Family Caregiving, Kinship Networks, and Caregiver Support", "description": "This section treats caregiving as a social system, policy issue, clinical concern, and site of inequity.", "children": [{"id": "d67619a8-0fe5-4a5b-8dde-9cfa886e5d5a", "type": "subtopic", "title": "Family caregiving systems", "children": [{"id": "59de0455-c391-438b-90d3-0d4e461e158b", "type": "concept", "title": "Caregiver roles and expectations"}, {"id": "5374d4d2-b886-4258-986e-893089a4cbff", "type": "concept", "title": "Intergenerational dynamics"}, {"id": "64791931-23a3-4eef-abae-6c27e281c3cb", "type": "concept", "title": "Kinship, chosen family, and nontraditional supports"}], "description": "Students learn that care is often distributed across relatives, friends, neighbors, paid workers, and community institutions."}, {"id": "2be04ecd-d2f3-4cb9-a75c-97ebe3fa26f5", "type": "subtopic", "title": "Caregiver burden and support", "children": [{"id": "cc6087f1-be12-4421-82e1-0c09cf809915", "type": "concept", "title": "Burden, depression, employment strain, and financial stress"}, {"id": "c8bca90a-d6e9-4a73-899a-538a1f2c7225", "type": "concept", "title": "Respite, psychoeducation, and support groups"}, {"id": "c1c4a5ae-cc66-4d20-9cae-c4e593ea4ddf", "type": "concept", "title": "Safety planning and emergency backup care"}], "description": "The point is to identify stress early and build practical supports before crisis or burnout."}, {"id": "4c816c67-b005-4a50-bc69-e66c3e448c59", "type": "subtopic", "title": "Caregiving equity", "children": [{"id": "90cda271-76f9-4d4a-8edb-f8ac8f98e4d8", "type": "concept", "title": "Women and care labor"}, {"id": "e9cad3c0-eca0-453c-8a3d-e52c4e81a1c6", "type": "concept", "title": "Immigrant care workers and labor rights"}, {"id": "00e333bb-0278-4267-a34f-ab02f8ddc630", "type": "concept", "title": "Culturally responsive caregiver assessment"}], "description": "Students examine how gender, class, race, immigration status, and disability shape unpaid and paid care."}]}, {"id": "5eac6b03-cd54-4394-b3a2-d995d7a320e1", "type": "topic", "title": "Long-Term Services and Supports, Aging in Place, and Care Transitions", "description": "This section helps students understand the settings and supports that shape aging in place, long-term care, and care transitions.", "children": [{"id": "a7c17b99-bc70-4bd7-8433-6b6b389cfdae", "type": "subtopic", "title": "Aging in place and home-based supports", "children": [{"id": "86137622-90ec-438f-a95a-79ef7738a6b7", "type": "concept", "title": "Home modifications and assistive devices"}, {"id": "cc63a17c-df24-4f6b-8c7a-f687451ab668", "type": "concept", "title": "Meals, transportation, personal care, and adult day services"}, {"id": "8f62cc9e-c462-4c4b-b11b-19eae0dfa0a1", "type": "concept", "title": "Risk, autonomy, and harm-reduction planning"}], "description": "Students learn to evaluate when home is safe, sustainable, and aligned with client goals."}, {"id": "926cf572-2459-4104-b994-51a4e5f63eab", "type": "subtopic", "title": "Long-term care settings", "children": [{"id": "84e4c784-abc9-4dc5-b237-0c6438e7f110", "type": "concept", "title": "Independent living, assisted living, nursing facilities, and memory care"}, {"id": "d03537c5-d311-47c9-bf12-9ad479c1df24", "type": "concept", "title": "Resident rights and quality indicators"}, {"id": "fdd47759-3ac2-438a-a945-236c2aa1d6d0", "type": "concept", "title": "Discharge planning and family conferences"}], "description": "This subtopic explains the continuum of care and the social worker's role across settings."}, {"id": "7e6fbfea-16e5-4384-9c51-a58d9411cee6", "type": "subtopic", "title": "Care transitions", "children": [{"id": "944a5aeb-863c-41a4-8182-83088d45c373", "type": "concept", "title": "Hospital-to-home transitions"}, {"id": "a80dabab-fca8-4444-9e9e-a95c16310c37", "type": "concept", "title": "Rehabilitation and skilled nursing episodes"}, {"id": "2dc7df75-b099-4693-9add-5d83e9057a5b", "type": "concept", "title": "Warm handoffs and follow-up"}], "description": "Students learn why transitions are high-risk moments for medication errors, rehospitalization, caregiver strain, and service gaps."}]}, {"id": "ace30ecf-9a33-40da-995f-c6ff244240aa", "type": "topic", "title": "Health Systems, Interprofessional Geriatric Care, and Care Coordination", "description": "This section teaches students to work inside interprofessional geriatric systems while keeping social work values visible.", "children": [{"id": "96f7f1f0-c08e-457e-b199-e4825abe91de", "type": "subtopic", "title": "Interprofessional team practice", "children": [{"id": "91f9c27b-a89a-439f-ad13-c5d0da8cbe24", "type": "concept", "title": "Team roles and scopes of practice"}, {"id": "0693c953-243c-4f2f-a316-88af11df5d10", "type": "concept", "title": "Case conferences and care plans"}, {"id": "2f577119-92e8-4245-9828-b51f06d8c177", "type": "concept", "title": "Conflict, hierarchy, and advocacy in teams"}], "description": "Gerontological social workers must communicate clearly with medicine, nursing, rehabilitation, pharmacy, behavioral health, and community partners."}, {"id": "955e4077-3968-4c53-9e1f-f37125345a1b", "type": "subtopic", "title": "Medication and treatment complexity", "children": [{"id": "830315ba-c133-4801-931c-f9436fe8da0e", "type": "concept", "title": "Polypharmacy and Beers Criteria awareness"}, {"id": "e5bfcb64-e3b5-41d0-87c6-88b8e05fa1c0", "type": "concept", "title": "Adherence barriers and health literacy"}, {"id": "d1f172b6-a8dc-4084-9399-4673d834c98d", "type": "concept", "title": "High-value care and Choosing Wisely principles"}], "description": "Students do not become prescribers, but they learn to recognize social-work-relevant medication risks and communication needs."}, {"id": "1417b8b9-4edf-477d-bcb7-566b0c2de71c", "type": "subtopic", "title": "Care coordination and navigation", "children": [{"id": "4f2407f2-9f52-4401-9957-1248f5c49a07", "type": "concept", "title": "Closed-loop referrals"}, {"id": "2cd6c5f2-7c4f-4707-83c3-1b9969e297bf", "type": "concept", "title": "Patient portals and information sharing"}, {"id": "98898221-0aeb-441a-aa6c-37778388f42c", "type": "concept", "title": "Crisis planning and continuity of care"}], "description": "This subtopic teaches students to reduce fragmentation by aligning services, benefits, goals, and responsible parties."}]}, {"id": "c33f18ed-a5d7-40a0-a18a-babb82ed1a11", "type": "topic", "title": "Elder Mistreatment, Safety, Guardianship, and Ethical Risk", "description": "This section prepares students for one of the field's hardest tasks: responding to mistreatment and risk while respecting autonomy.", "children": [{"id": "c70108eb-a4f9-41ae-992b-7427a1a1c51b", "type": "subtopic", "title": "Elder abuse, neglect, and exploitation", "children": [{"id": "a49a75d2-5576-4e82-9da9-5a60fee7207e", "type": "concept", "title": "Physical, emotional, sexual abuse and neglect"}, {"id": "699c9831-9fe5-401e-9695-88fa84609e91", "type": "concept", "title": "Financial exploitation and scams"}, {"id": "d2957ec5-9471-459a-a517-43033d188567", "type": "concept", "title": "Self-neglect and environmental risk"}], "description": "Students learn to identify mistreatment while avoiding simplistic assumptions about families, culture, capacity, or dependency."}, {"id": "3831d151-0fe9-44c9-a109-35381845dfbc", "type": "subtopic", "title": "Mandated reporting and safety planning", "children": [{"id": "64d4e19f-c1b1-400d-b78a-834535a5d0a9", "type": "concept", "title": "State reporting pathways"}, {"id": "c6f512a5-f498-407d-b9ba-67d7b4bca1e9", "type": "concept", "title": "Risk assessment and documentation"}, {"id": "3ab60391-09b3-48b9-b3be-bcd8bf9a9c9f", "type": "concept", "title": "Emergency shelter, protective services, and legal referrals"}], "description": "The focus is careful action: meet legal duties, protect safety, and preserve dignity wherever possible."}, {"id": "4a2d76bd-3c85-4c5f-a544-c1794d126ec5", "type": "subtopic", "title": "Guardianship, capacity, and rights", "children": [{"id": "f38cc1a2-1bdd-4154-be38-a98151809178", "type": "concept", "title": "Capacity versus competency"}, {"id": "7dce1272-5671-44db-a089-2be86ee2e884", "type": "concept", "title": "Supported decision-making and least restrictive alternatives"}, {"id": "1795e231-82bb-4bf5-9892-1fb6ecb7cdde", "type": "concept", "title": "Guardianship, conservatorship, and advance planning"}], "description": "Students examine the tension between protection and autonomy in high-stakes decisions."}]}, {"id": "977e4ecb-b023-4214-8be2-d4ee3e7e2ac3", "type": "topic", "title": "End-of-Life Care, Advance Care Planning, Palliative Care, and Bereavement", "description": "This section develops skill in serious-illness, death, dying, and bereavement conversations across cultures and care systems.", "children": [{"id": "215629f4-a353-4f16-a17e-1cad1c837d7a", "type": "subtopic", "title": "Advance care planning", "children": [{"id": "a022df01-1230-44a9-bad1-720b8740000a", "type": "concept", "title": "Health care proxies and advance directives"}, {"id": "4094eac6-3b0f-440a-9d34-5772be59252a", "type": "concept", "title": "Goals-of-care conversations"}, {"id": "802c6e7d-7481-4c39-bd89-4b7fc00cbf95", "type": "concept", "title": "Cultural and family considerations"}], "description": "Students learn to facilitate values-based conversations before crisis, not simply collect forms."}, {"id": "b19bc4c6-c615-47fe-bb94-d3b7f0511e6a", "type": "subtopic", "title": "Palliative and hospice care", "children": [{"id": "2e802c4f-b668-4eed-86d0-624c878cbc92", "type": "concept", "title": "Palliative care across serious illness"}, {"id": "85075ec7-02f6-46cc-9528-f62b3f8ea6ab", "type": "concept", "title": "Hospice eligibility and services"}, {"id": "73585470-7633-47ab-bf4a-908d54fc92f2", "type": "concept", "title": "Pain, suffering, dignity, and spiritual care"}], "description": "This subtopic clarifies how comfort, quality of life, symptom burden, and family support fit social work practice."}, {"id": "19f95e7a-9283-4fa0-9e1b-9823213b62b6", "type": "subtopic", "title": "Bereavement and mourning", "children": [{"id": "43610983-e36c-4a02-be39-dd8670768cfd", "type": "concept", "title": "Anticipatory grief"}, {"id": "10e6d099-93a5-4a1e-a462-035b8bc5aa61", "type": "concept", "title": "Complicated grief and traumatic loss"}, {"id": "613658f8-1501-4693-a8fb-341227a16eb2", "type": "concept", "title": "Ritual, culture, and continuing bonds"}], "description": "Students learn to support caregivers and communities before and after death."}]}, {"id": "b337ff01-86dc-4b9d-8317-2d1bc9c03f18", "type": "topic", "title": "Aging, Diversity, Equity, Culture, and Anti-Oppressive Practice", "description": "This section places equity at the center of gerontological social work, because later-life outcomes reflect decades of unequal opportunity and exposure.", "children": [{"id": "95ba3159-bfb9-4f1d-9386-5e6359d3a517", "type": "subtopic", "title": "Intersectional aging", "children": [{"id": "1498d6d9-4a7a-4ec5-8303-8ae947d39ccd", "type": "concept", "title": "Race, ethnicity, language, class, gender, sexuality, disability, religion"}, {"id": "f436bbfb-eaf6-41b9-9075-1587334c07f6", "type": "concept", "title": "Immigration, refugee status, and documentation"}, {"id": "5b75d579-5e60-4c1b-88d3-5d5679f56357", "type": "concept", "title": "Rural, tribal, and place-based aging"}], "description": "Students learn to understand aging through multiple identities and unequal life chances."}, {"id": "7a0c905a-a614-4878-bf18-c07e25d95a68", "type": "subtopic", "title": "Health disparities and structural inequity", "children": [{"id": "43fd68ae-0461-4b3f-8fc7-4977033b1ee9", "type": "concept", "title": "Racism and weathering"}, {"id": "72fcad2d-cfdf-4fc7-9f15-41e1122632d3", "type": "concept", "title": "Disability justice and accessibility"}, {"id": "ed4efcea-40be-484b-b78b-886f9c66b1bc", "type": "concept", "title": "Housing, food, transportation, and digital inequity"}], "description": "This subtopic connects client-level assessment to upstream conditions that shape aging outcomes."}, {"id": "3c76208c-01e3-4202-9477-2f3b0d54550c", "type": "subtopic", "title": "Culturally responsive and anti-oppressive practice", "children": [{"id": "c3359a38-0bd3-4268-b768-f735090164e7", "type": "concept", "title": "Cultural formulation and explanatory models"}, {"id": "c503db88-81e3-4ca9-bd94-8a599291b6c5", "type": "concept", "title": "Language access and interpreter use"}, {"id": "6dcf4430-5485-4748-a9d3-2ac76252538f", "type": "concept", "title": "Power, bias, and reflective supervision"}], "description": "Students practice humility, accountability, and partnership instead of one-size-fits-all cultural checklists."}]}, {"id": "b7da88ae-38f9-40af-84d2-6ad5121ae20f", "type": "topic", "title": "Aging Policy, Medicare, Medicaid, Social Security, Housing, and Advocacy", "description": "This section gives students the policy and benefits literacy needed to advocate effectively with and for older adults.", "children": [{"id": "ff6e2441-2965-42eb-b87c-617b9424ce31", "type": "subtopic", "title": "Income security and retirement policy", "children": [{"id": "88d7b66e-9d61-4aa9-a6c3-c3cacde2c259", "type": "concept", "title": "Social Security, SSI, pensions, and savings"}, {"id": "b66079d1-38c9-4e03-a089-d004a7b1b12f", "type": "concept", "title": "Older adult poverty and debt"}, {"id": "b109820a-2f83-4f1e-bccd-0df73703f12d", "type": "concept", "title": "Employment, age discrimination, and retirement timing"}], "description": "Students learn how Social Security, pensions, work histories, and poverty affect client choices."}, {"id": "879ef157-de4b-4cbf-a6c6-d18cf8b1c674", "type": "subtopic", "title": "Health and long-term care financing", "children": [{"id": "0c9898c8-7fae-4c1a-923f-09e078c1534c", "type": "concept", "title": "Medicare Parts A, B, C, and D"}, {"id": "cebf30d3-0a07-49f6-bdff-b0ff0266760a", "type": "concept", "title": "Medicaid eligibility and long-term services"}, {"id": "5e065df0-faea-4f73-a986-2c8858a42e3f", "type": "concept", "title": "Dual eligibility and spend-down issues"}], "description": "This subtopic makes Medicare, Medicaid, private insurance, and out-of-pocket costs understandable for practice."}, {"id": "f4d9200e-969b-48c3-9e3c-e21810dee949", "type": "subtopic", "title": "Housing, civil rights, and advocacy", "children": [{"id": "ff440a7e-3d3d-4e8e-93d2-3cb1434eceaa", "type": "concept", "title": "Older Americans Act and aging services"}, {"id": "14f5130a-f9e1-4939-90a5-a2d8f2970ca5", "type": "concept", "title": "Affordable housing and homelessness prevention"}, {"id": "cb030d86-5d02-43d6-a11e-b7b31b47f735", "type": "concept", "title": "Legislative advocacy and coalition work"}], "description": "Students learn to move from individual resource referral to policy advocacy."}]}, {"id": "c307b903-9717-4bc2-926c-d8e6f855cfbd", "type": "topic", "title": "Community-Based Aging Networks, Benefits Access, and Resource Navigation", "description": "This section makes the aging-services ecosystem practical, navigable, and programmatically useful.", "children": [{"id": "e85fa7a8-7f5f-4033-8140-c755a0ae5e0e", "type": "subtopic", "title": "Aging network structure", "children": [{"id": "8782b473-c50c-4b6b-830b-8bfe814c59b7", "type": "concept", "title": "Area Agencies on Aging"}, {"id": "465ec77d-9ded-4151-ba9a-450714d34ede", "type": "concept", "title": "Aging and Disability Resource Centers"}, {"id": "21dbaece-23d4-4b8e-8cf0-1603dac32e59", "type": "concept", "title": "Senior centers, ombuds programs, and community partners"}], "description": "Students learn the service ecosystem so they can navigate it confidently with clients."}, {"id": "bb63599a-0a31-4474-aa41-de7fd5eff943", "type": "subtopic", "title": "Benefits and resource navigation", "children": [{"id": "dc9da7f3-08e3-4d7f-983e-754a8a4e9596", "type": "concept", "title": "SNAP, LIHEAP, Medicare Savings Programs, and prescription help"}, {"id": "558b5222-f7df-4176-b1cd-5e5ac83ae453", "type": "concept", "title": "Transportation, meals, legal aid, and caregiver supports"}, {"id": "60788aba-ff88-4143-b50b-c3d98f0b752c", "type": "concept", "title": "Documentation and eligibility barriers"}], "description": "This subtopic teaches practical screening, referral, and follow-through skills."}, {"id": "ce97d523-8d70-4fbe-aef4-606d0dc10eb4", "type": "subtopic", "title": "Community practice and program development", "children": [{"id": "ee570e0a-6ea8-4e78-853e-4a0d9991d36a", "type": "concept", "title": "Needs assessment and asset mapping"}, {"id": "57c401b5-1161-463e-8af2-e4dfb79a750b", "type": "concept", "title": "Partnerships and outreach"}, {"id": "0f56ef16-0dd1-4395-911a-8ec63e0561ac", "type": "concept", "title": "Program evaluation and continuous improvement"}], "description": "Students learn to design responsive programs with older adults rather than for them."}]}, {"id": "45e2aa58-d512-4954-9c21-8b8e8d6f9c9c", "type": "topic", "title": "Technology, Telehealth, Accessibility, and Innovation in Aging Services", "description": "This section asks students to evaluate technology as a tool for autonomy and access, but also as a source of exclusion, surveillance, and bias.", "children": [{"id": "35292a9c-c012-4b49-90a0-3d18896ca704", "type": "subtopic", "title": "Telehealth and digital inclusion", "children": [{"id": "a76f5b4f-5bcb-4e71-9c4b-499cc5970a92", "type": "concept", "title": "Telehealth etiquette and privacy"}, {"id": "443cdb54-6439-421d-b6f2-e8979786fed6", "type": "concept", "title": "Broadband, device access, and digital literacy"}, {"id": "e9a22ceb-3a21-4e62-8153-e5b2dcbd107e", "type": "concept", "title": "Accessibility and language supports"}], "description": "Students examine how technology can expand access while also excluding people without devices, broadband, literacy, or trust."}, {"id": "db04e605-14ff-45b9-984f-df3f38c1c91e", "type": "subtopic", "title": "Assistive and smart-home technologies", "children": [{"id": "2e272e81-23d3-4cd7-b381-57e2b4bdc18f", "type": "concept", "title": "Medication reminders, fall detection, and sensors"}, {"id": "398d1a7a-8359-4045-890b-007eda22357a", "type": "concept", "title": "Mobility, vision, hearing, and communication aids"}, {"id": "96488fb1-5fd1-41ed-908c-0c485d3ab196", "type": "concept", "title": "Ethical concerns about monitoring and consent"}], "description": "This subtopic helps students evaluate tools that support autonomy, safety, and caregiver communication."}, {"id": "f2c11e7a-ba6f-4adb-8b04-971f9a59264a", "type": "subtopic", "title": "Innovation and risk", "children": [{"id": "88c4c95e-f9fd-4e7c-85c0-5fb4590c3369", "type": "concept", "title": "AI triage and bias"}, {"id": "24834568-3710-44e6-a886-5f60395dc87d", "type": "concept", "title": "Data privacy and surveillance"}, {"id": "6fde89db-9177-4f3d-80aa-0b6fe336a806", "type": "concept", "title": "Implementation, training, and evaluation"}], "description": "Students learn to ask whether new tools are effective, equitable, secure, and compatible with social-work values."}]}, {"id": "ec19ff94-85bf-4e7f-a37c-9795fab7b430", "type": "topic", "title": "Professional Ethics, Documentation, Self-Care, and Field Integration", "description": "This final section integrates professional identity, ethics, documentation, supervision, self-care, and field-based application.", "children": [{"id": "bf52a990-7f58-4280-997d-4dc3f302c397", "type": "subtopic", "title": "Professional ethics in gerontological practice", "children": [{"id": "eeadab75-d5d7-436b-8cdd-308ae7327a32", "type": "concept", "title": "NASW Code of Ethics applications"}, {"id": "5c3908be-f249-4f84-8d04-4b87f6f63109", "type": "concept", "title": "Dual relationships and family pressure"}, {"id": "47d11a36-59e8-4a43-9758-2157ed5f2564", "type": "concept", "title": "Confidentiality with caregivers and teams"}], "description": "Students integrate autonomy, dignity, confidentiality, informed consent, boundaries, and social justice in complex aging cases."}, {"id": "6c75bb37-f69c-4999-8eef-77c97e9b0105", "type": "subtopic", "title": "Documentation and supervision", "children": [{"id": "647dac1f-ed88-4000-9d23-ce207d609d19", "type": "concept", "title": "Assessment notes and service plans"}, {"id": "b22b100b-0fc4-4fb8-bf30-775b26e60cc0", "type": "concept", "title": "Risk documentation"}, {"id": "16b0a07e-7894-42a7-a4b1-45db871f4add", "type": "concept", "title": "Supervision, consultation, and interprofessional records"}], "description": "This subtopic builds the habit of clear, defensible, strengths-based records and reflective consultation."}, {"id": "f35389fe-35d8-4fda-b1e7-22ea34211af8", "type": "subtopic", "title": "Field integration and practitioner sustainability", "children": [{"id": "5e3e209c-5212-4752-91af-bcbd71b3c75a", "type": "concept", "title": "Use of self and reflective practice"}, {"id": "a2857e08-b9ec-4bf3-97d7-77bb89642309", "type": "concept", "title": "Secondary trauma and grief exposure"}, {"id": "18947087-c987-4d9f-8bf2-5251ed338939", "type": "concept", "title": "Capstone presentation and professional development plan"}], "description": "Students connect classroom knowledge to field learning while protecting against burnout and moral distress."}]}], "dbBacked": true}$agswjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'aging-gerontological-social-work'
);

update public.learning_paths
set
  title = 'Aging / Gerontological Social Work',
  goal = 'Aging / Gerontological Social Work',
  summary = 'Aging / Gerontological Social Work prepares students to practice with older adults, caregivers, families, organizations, and communities in a rapidly aging society. Students learn aging demographics, life-course development, physical and cognitive aging, psychosocial aging, caregiving, long-term services, elder mistreatment, end-of-life care, aging policy, diversity, and evidence-informed social work practice. The course emphasizes person-in-environment assessment, dignity, autonomy, cultural humility, anti-oppressive practice, interprofessional care, and practical navigation of aging-service systems.',
  data = $agswjson${"slug": "aging-gerontological-social-work", "title": "Aging / Gerontological Social Work", "description": "Aging / Gerontological Social Work prepares students to practice with older adults, caregivers, families, organizations, and communities in a rapidly aging society. Students learn aging demographics, life-course development, physical and cognitive aging, psychosocial aging, caregiving, long-term services, elder mistreatment, end-of-life care, aging policy, diversity, and evidence-informed social work practice. The course emphasizes person-in-environment assessment, dignity, autonomy, cultural humility, anti-oppressive practice, interprofessional care, and practical navigation of aging-service systems.", "topics": [{"id": "4e153b3d-62a2-427c-ab46-7b5ece37c129", "type": "topic", "title": "Demographics, Longevity, and the Aging Society", "description": "This opening section gives students the map of aging: who is aging, where, under what social conditions, and why those patterns matter for social work practice and policy.", "children": [{"id": "f505b1de-df93-40ea-96d6-2c3fa1556e1f", "type": "subtopic", "title": "Population aging and longevity", "children": [{"id": "de957a3e-c27a-4a0f-a4a8-ce6c3b4f2e97", "type": "concept", "title": "Age pyramids and dependency ratios"}, {"id": "46357cde-6fa4-460f-a78d-14637ff2d335", "type": "concept", "title": "Life expectancy, health expectancy, and compression of morbidity"}, {"id": "474fd8af-3531-42c2-bf41-671212483461", "type": "concept", "title": "Global, national, state, and local aging trends"}], "description": "Students learn why aging is a central social-work issue: longer lives reshape families, labor markets, health systems, housing, and public budgets."}, {"id": "e426a7eb-2c96-426d-ab73-06901ad1bb89", "type": "subtopic", "title": "Social determinants of aging", "children": [{"id": "e8c20a7e-6eb7-44c9-afc8-648a0e9718c6", "type": "concept", "title": "Cumulative advantage and disadvantage"}, {"id": "a5b53929-3a82-4d43-8275-424a8e7a69ad", "type": "concept", "title": "Place, environment, and age-friendly communities"}, {"id": "a701fe61-8408-4fdc-95cb-99d33cf23769", "type": "concept", "title": "Poverty, wealth, work history, and retirement security"}], "description": "This subtopic links older-adult outcomes to housing, income, racism, neighborhood conditions, food access, transportation, and social connection."}, {"id": "991cfa1d-1ade-45a8-8150-f2b13623e192", "type": "subtopic", "title": "Ageism and the social construction of later life", "children": [{"id": "0ccdb46e-09e5-4670-937f-22f98d39778f", "type": "concept", "title": "Implicit and explicit ageism"}, {"id": "b6cdd6a9-eb2b-4394-8835-74b6af719882", "type": "concept", "title": "Language and representation"}, {"id": "49c7a377-2d2b-4895-8450-c27b944260dc", "type": "concept", "title": "Anti-ageist practice and advocacy"}], "description": "Students examine how stereotypes shape practice, policy, employment, health care, media, and older adults' self-understanding."}]}, {"id": "97c60dfa-3ac5-46ab-9281-b082ce7e8643", "type": "topic", "title": "Theories of Aging, Life Course, and Person-in-Environment Practice", "description": "This section gives students the conceptual language to understand later life through development, environment, identity, social structure, and lived experience.", "children": [{"id": "cd09256d-cec3-4820-ae68-f6606860b409", "type": "subtopic", "title": "Life-course and ecological frameworks", "children": [{"id": "98512dc6-67d4-46c6-bd90-23cea0a470ea", "type": "concept", "title": "Person-in-environment assessment"}, {"id": "bfcde410-1a21-42ad-8795-d665703262e0", "type": "concept", "title": "Life-course transitions and turning points"}, {"id": "108960bf-0405-48ae-b2b4-510d7898f058", "type": "concept", "title": "Ecological systems across micro, mezzo, and macro levels"}], "description": "The point is to see aging as a developmental, relational, cultural, and structural process rather than a purely individual condition."}, {"id": "9d6fea8d-b81b-465d-9357-fa898a5dea44", "type": "subtopic", "title": "Theories of aging", "children": [{"id": "988d7241-61d9-4e36-9b59-11b40afff451", "type": "concept", "title": "Continuity, activity, disengagement, and modernization theories"}, {"id": "b037584c-2cd0-43d5-9a27-4713157607f5", "type": "concept", "title": "Selective optimization with compensation"}, {"id": "2b4487d4-dadf-4656-badb-733a5b07007f", "type": "concept", "title": "Critical gerontology and political economy of aging"}], "description": "Theory helps students interpret adaptation, continuity, loss, role change, wisdom, disengagement, activity, and successful aging without reducing clients to one model."}, {"id": "5126293d-93cb-45bf-b59e-36b6ad6cc943", "type": "subtopic", "title": "Strengths and resilience perspectives", "children": [{"id": "71eaa661-7568-4e31-9635-8e9f8047496e", "type": "concept", "title": "Narrative and life review"}, {"id": "0adfa24d-2a90-4ebf-bf96-71591cc9128c", "type": "concept", "title": "Resilience under adversity"}, {"id": "491861f0-10dc-4373-8270-20db288fafd7", "type": "concept", "title": "Protective factors and community assets"}], "description": "Students learn to identify capacities, relationships, meaning, and cultural resources alongside risk and need."}]}, {"id": "8496743b-2538-4b9b-9cde-a1121a957d3b", "type": "topic", "title": "Physical Aging, Functional Ability, Frailty, and Chronic Conditions", "description": "This section builds practice literacy around physical aging, function, disability, frailty, and chronic illness without reducing older adults to diagnoses.", "children": [{"id": "9657debb-b47a-4142-aca7-850ce6c3c977", "type": "subtopic", "title": "Normal aging and functional change", "children": [{"id": "22639735-159c-4aaa-82dd-620ca2dd41de", "type": "concept", "title": "Sensory change, mobility, sleep, nutrition, and pain"}, {"id": "9bb5c80f-3af4-4e3d-97a1-bb82be12f7a2", "type": "concept", "title": "Activities of daily living and instrumental activities"}, {"id": "f693789a-16fd-4d74-83ba-0a1258d3c459", "type": "concept", "title": "Universal design and environmental fit"}], "description": "Students distinguish expected physical aging from disease, disability, neglect, and remediable environmental barriers."}, {"id": "1f1c56d7-c0b8-4c0b-b3cc-fdf7715db2a5", "type": "subtopic", "title": "Frailty, falls, and geriatric syndromes", "children": [{"id": "3c60f9ed-9095-472f-8333-d84eaaa0872f", "type": "concept", "title": "Frailty phenotype and cumulative deficit models"}, {"id": "9a9088b9-e0d5-4c7d-9f10-c7259167466f", "type": "concept", "title": "Falls risk and mobility supports"}, {"id": "db016a88-772b-4b91-9a7c-2e0bca8063ff", "type": "concept", "title": "Incontinence, pressure injuries, and malnutrition"}], "description": "This material prepares students to spot high-risk patterns that require coordinated assessment, prevention, and referral."}, {"id": "9ab5700c-fec9-49d9-b7d3-a94de225828a", "type": "subtopic", "title": "Chronic illness and multimorbidity", "children": [{"id": "467dcc1b-18e7-4790-a236-7d1d14094b37", "type": "concept", "title": "Diabetes, cardiovascular disease, COPD, arthritis, osteoporosis"}, {"id": "dd829ab1-f36a-48a8-b69c-f79d02b15d60", "type": "concept", "title": "Self-management and health literacy"}, {"id": "cef7ae77-fa4c-4700-abe1-e1c769c20444", "type": "concept", "title": "Medication burden and deprescribing conversations"}], "description": "Students learn how multiple conditions interact with poverty, caregiving, adherence, disability, and care fragmentation."}]}, {"id": "f173f4ba-46e1-4c09-83dd-acbe83d17629", "type": "topic", "title": "Cognitive Aging, Dementia, Delirium, and Mental Health", "description": "This section prepares students to address cognition and mental health with accuracy, humility, and practical referral awareness.", "children": [{"id": "bb5b80f7-16f6-486b-a384-c759bef62059", "type": "subtopic", "title": "Cognitive aging and screening", "children": [{"id": "bbfa3248-7c6f-4fbb-8983-528dd49a3ec5", "type": "concept", "title": "Normal cognitive aging"}, {"id": "56ceba11-7ab1-4621-8f72-66ddff391d04", "type": "concept", "title": "Mild cognitive impairment"}, {"id": "f9c58254-0bf2-4daf-8780-3d37a8482b23", "type": "concept", "title": "Screening tools and referral pathways"}], "description": "Students learn to discuss memory and cognition respectfully, screen appropriately, and recognize when specialized evaluation is needed."}, {"id": "dcde475e-eda9-4d16-aa28-bdc504d7d9fa", "type": "subtopic", "title": "Dementia, delirium, and decision-making", "children": [{"id": "cf430a14-9ac0-4318-bcc0-bf06d6ef0e71", "type": "concept", "title": "Alzheimer's disease and related dementias"}, {"id": "d90005bf-cc5d-4805-8411-91231cc7bb50", "type": "concept", "title": "Delirium warning signs"}, {"id": "20d75a46-4c53-42ec-9472-42ee73be4058", "type": "concept", "title": "Supported decision-making and capacity questions"}], "description": "This subtopic teaches students to differentiate chronic cognitive decline from acute confusion and to support safety without erasing autonomy."}, {"id": "2723c050-6c84-4ce8-aa41-666d81354836", "type": "subtopic", "title": "Mental health and substance use in later life", "children": [{"id": "c057cfcb-f473-492e-8a53-07ba795bd83f", "type": "concept", "title": "Depression, anxiety, grief, trauma, and suicide risk"}, {"id": "eb60f761-2d94-47aa-a648-2c1bcb0a230a", "type": "concept", "title": "Alcohol, medication, and substance-use concerns"}, {"id": "62d7c987-9a54-471b-935e-7208bd768424", "type": "concept", "title": "Integrated behavioral health and referral"}], "description": "Students practice recognizing underdiagnosed distress and risk among older adults."}]}, {"id": "7863ebb0-1f13-46d1-aa29-54c23847c51f", "type": "topic", "title": "Psychosocial Aging, Identity, Meaning, Grief, and Resilience", "description": "This section centers the emotional, relational, cultural, and existential dimensions of later life.", "children": [{"id": "cdf3f7b8-0eae-4cd1-ab20-d774a16c4434", "type": "subtopic", "title": "Identity, roles, and meaning", "children": [{"id": "f0e28f9a-951b-402e-ad70-405530e69e36", "type": "concept", "title": "Retirement and work identity"}, {"id": "09cb9d4a-480b-476c-8068-7698b1573902", "type": "concept", "title": "Grandparenting, friendship, intimacy, and sexuality"}, {"id": "560ea276-7183-4b7a-8676-f3210d862943", "type": "concept", "title": "Spirituality, meaning, and life review"}], "description": "Later life often brings role transitions, but also creativity, contribution, sexuality, spirituality, and renewed purpose."}, {"id": "aea35c8a-0bfd-4437-a81f-c33db136db19", "type": "subtopic", "title": "Social isolation and loneliness", "children": [{"id": "444c810f-d97e-469d-819e-31202e863a86", "type": "concept", "title": "Risk and protective factors"}, {"id": "08ab18b3-4971-4ace-b8d1-c50d3487721c", "type": "concept", "title": "Community connection and mutual aid"}, {"id": "f43d23c4-ca53-4ceb-a729-9bcdbe0047b1", "type": "concept", "title": "Technology-mediated connection and its limits"}], "description": "Students learn why isolation is both a clinical and public-health issue and how to intervene beyond generic referral lists."}, {"id": "b8c49639-db05-46c0-aa07-61153c677c14", "type": "subtopic", "title": "Loss, grief, and resilience", "children": [{"id": "ba1535b7-5df6-4914-a9f8-a3c705fe9426", "type": "concept", "title": "Complicated grief and trauma histories"}, {"id": "d6a61a64-df97-4e9d-8fb2-455c6f0a524f", "type": "concept", "title": "Ambiguous loss in dementia and caregiving"}, {"id": "9adb2975-b34e-49f1-a101-ab86672fce19", "type": "concept", "title": "Resilience practices and culturally grounded mourning"}], "description": "This subtopic equips students to work with bereavement, ambiguous loss, disability-related loss, and accumulated life transitions."}]}, {"id": "5d46869c-95b5-4f48-909d-cb6c8e5ed3b2", "type": "topic", "title": "Assessment, Engagement, and Evidence-Informed Practice with Older Adults", "description": "This section turns course knowledge into practice skill by teaching students how to assess, engage, plan, and evaluate with older adults.", "children": [{"id": "d4091bec-6ff7-48ee-8b5d-65ff27045d39", "type": "subtopic", "title": "Comprehensive gerontological assessment", "children": [{"id": "486c39c5-ca0a-4f40-b948-18ab96f138fd", "type": "concept", "title": "Presenting concern, strengths, and goals"}, {"id": "9ceef5b9-1064-4286-99ae-d11cc8b14ca6", "type": "concept", "title": "ADLs, IADLs, cognition, mood, safety, and social supports"}, {"id": "673f6bcc-8f65-4705-9789-b81b1a28274d", "type": "concept", "title": "Housing, benefits, transportation, and legal needs"}], "description": "Students learn to synthesize biopsychosocial-spiritual, functional, cognitive, environmental, cultural, and financial information."}, {"id": "1eb8a456-6878-45d4-851f-4e958a245344", "type": "subtopic", "title": "Engagement and interviewing", "children": [{"id": "a15fa4cb-c388-41ec-86b5-cb4b3a513cb9", "type": "concept", "title": "Motivational interviewing and shared decision-making"}, {"id": "9c9ed2fe-1164-4203-8292-204f34dc585b", "type": "concept", "title": "Communication adaptations"}, {"id": "76a1f040-1290-4213-ad29-858cf14863dc", "type": "concept", "title": "Working with interpreters and family participants"}], "description": "The aim is to build trust while adapting to hearing, vision, cognition, trauma histories, culture, and family dynamics."}, {"id": "bca8f1ac-3599-454b-b4cd-983b569a9099", "type": "subtopic", "title": "Evidence-informed intervention planning", "children": [{"id": "386b2f2b-d656-46ca-afcd-2a420e695c4e", "type": "concept", "title": "SMART goals and service plans"}, {"id": "ab468e1f-c50c-4b91-b2b4-fa705e92b1c0", "type": "concept", "title": "Brief interventions and referrals"}, {"id": "f63900a2-7c65-4fea-ab70-aa10acf9777c", "type": "concept", "title": "Monitoring, follow-up, and outcome tracking"}], "description": "Students connect assessment findings to interventions that are realistic, ethical, measurable, and person-centered."}]}, {"id": "a471f005-9873-44bc-8ac5-d4e7277afbb7", "type": "topic", "title": "Family Caregiving, Kinship Networks, and Caregiver Support", "description": "This section treats caregiving as a social system, policy issue, clinical concern, and site of inequity.", "children": [{"id": "d67619a8-0fe5-4a5b-8dde-9cfa886e5d5a", "type": "subtopic", "title": "Family caregiving systems", "children": [{"id": "59de0455-c391-438b-90d3-0d4e461e158b", "type": "concept", "title": "Caregiver roles and expectations"}, {"id": "5374d4d2-b886-4258-986e-893089a4cbff", "type": "concept", "title": "Intergenerational dynamics"}, {"id": "64791931-23a3-4eef-abae-6c27e281c3cb", "type": "concept", "title": "Kinship, chosen family, and nontraditional supports"}], "description": "Students learn that care is often distributed across relatives, friends, neighbors, paid workers, and community institutions."}, {"id": "2be04ecd-d2f3-4cb9-a75c-97ebe3fa26f5", "type": "subtopic", "title": "Caregiver burden and support", "children": [{"id": "cc6087f1-be12-4421-82e1-0c09cf809915", "type": "concept", "title": "Burden, depression, employment strain, and financial stress"}, {"id": "c8bca90a-d6e9-4a73-899a-538a1f2c7225", "type": "concept", "title": "Respite, psychoeducation, and support groups"}, {"id": "c1c4a5ae-cc66-4d20-9cae-c4e593ea4ddf", "type": "concept", "title": "Safety planning and emergency backup care"}], "description": "The point is to identify stress early and build practical supports before crisis or burnout."}, {"id": "4c816c67-b005-4a50-bc69-e66c3e448c59", "type": "subtopic", "title": "Caregiving equity", "children": [{"id": "90cda271-76f9-4d4a-8edb-f8ac8f98e4d8", "type": "concept", "title": "Women and care labor"}, {"id": "e9cad3c0-eca0-453c-8a3d-e52c4e81a1c6", "type": "concept", "title": "Immigrant care workers and labor rights"}, {"id": "00e333bb-0278-4267-a34f-ab02f8ddc630", "type": "concept", "title": "Culturally responsive caregiver assessment"}], "description": "Students examine how gender, class, race, immigration status, and disability shape unpaid and paid care."}]}, {"id": "5eac6b03-cd54-4394-b3a2-d995d7a320e1", "type": "topic", "title": "Long-Term Services and Supports, Aging in Place, and Care Transitions", "description": "This section helps students understand the settings and supports that shape aging in place, long-term care, and care transitions.", "children": [{"id": "a7c17b99-bc70-4bd7-8433-6b6b389cfdae", "type": "subtopic", "title": "Aging in place and home-based supports", "children": [{"id": "86137622-90ec-438f-a95a-79ef7738a6b7", "type": "concept", "title": "Home modifications and assistive devices"}, {"id": "cc63a17c-df24-4f6b-8c7a-f687451ab668", "type": "concept", "title": "Meals, transportation, personal care, and adult day services"}, {"id": "8f62cc9e-c462-4c4b-b11b-19eae0dfa0a1", "type": "concept", "title": "Risk, autonomy, and harm-reduction planning"}], "description": "Students learn to evaluate when home is safe, sustainable, and aligned with client goals."}, {"id": "926cf572-2459-4104-b994-51a4e5f63eab", "type": "subtopic", "title": "Long-term care settings", "children": [{"id": "84e4c784-abc9-4dc5-b237-0c6438e7f110", "type": "concept", "title": "Independent living, assisted living, nursing facilities, and memory care"}, {"id": "d03537c5-d311-47c9-bf12-9ad479c1df24", "type": "concept", "title": "Resident rights and quality indicators"}, {"id": "fdd47759-3ac2-438a-a945-236c2aa1d6d0", "type": "concept", "title": "Discharge planning and family conferences"}], "description": "This subtopic explains the continuum of care and the social worker's role across settings."}, {"id": "7e6fbfea-16e5-4384-9c51-a58d9411cee6", "type": "subtopic", "title": "Care transitions", "children": [{"id": "944a5aeb-863c-41a4-8182-83088d45c373", "type": "concept", "title": "Hospital-to-home transitions"}, {"id": "a80dabab-fca8-4444-9e9e-a95c16310c37", "type": "concept", "title": "Rehabilitation and skilled nursing episodes"}, {"id": "2dc7df75-b099-4693-9add-5d83e9057a5b", "type": "concept", "title": "Warm handoffs and follow-up"}], "description": "Students learn why transitions are high-risk moments for medication errors, rehospitalization, caregiver strain, and service gaps."}]}, {"id": "ace30ecf-9a33-40da-995f-c6ff244240aa", "type": "topic", "title": "Health Systems, Interprofessional Geriatric Care, and Care Coordination", "description": "This section teaches students to work inside interprofessional geriatric systems while keeping social work values visible.", "children": [{"id": "96f7f1f0-c08e-457e-b199-e4825abe91de", "type": "subtopic", "title": "Interprofessional team practice", "children": [{"id": "91f9c27b-a89a-439f-ad13-c5d0da8cbe24", "type": "concept", "title": "Team roles and scopes of practice"}, {"id": "0693c953-243c-4f2f-a316-88af11df5d10", "type": "concept", "title": "Case conferences and care plans"}, {"id": "2f577119-92e8-4245-9828-b51f06d8c177", "type": "concept", "title": "Conflict, hierarchy, and advocacy in teams"}], "description": "Gerontological social workers must communicate clearly with medicine, nursing, rehabilitation, pharmacy, behavioral health, and community partners."}, {"id": "955e4077-3968-4c53-9e1f-f37125345a1b", "type": "subtopic", "title": "Medication and treatment complexity", "children": [{"id": "830315ba-c133-4801-931c-f9436fe8da0e", "type": "concept", "title": "Polypharmacy and Beers Criteria awareness"}, {"id": "e5bfcb64-e3b5-41d0-87c6-88b8e05fa1c0", "type": "concept", "title": "Adherence barriers and health literacy"}, {"id": "d1f172b6-a8dc-4084-9399-4673d834c98d", "type": "concept", "title": "High-value care and Choosing Wisely principles"}], "description": "Students do not become prescribers, but they learn to recognize social-work-relevant medication risks and communication needs."}, {"id": "1417b8b9-4edf-477d-bcb7-566b0c2de71c", "type": "subtopic", "title": "Care coordination and navigation", "children": [{"id": "4f2407f2-9f52-4401-9957-1248f5c49a07", "type": "concept", "title": "Closed-loop referrals"}, {"id": "2cd6c5f2-7c4f-4707-83c3-1b9969e297bf", "type": "concept", "title": "Patient portals and information sharing"}, {"id": "98898221-0aeb-441a-aa6c-37778388f42c", "type": "concept", "title": "Crisis planning and continuity of care"}], "description": "This subtopic teaches students to reduce fragmentation by aligning services, benefits, goals, and responsible parties."}]}, {"id": "c33f18ed-a5d7-40a0-a18a-babb82ed1a11", "type": "topic", "title": "Elder Mistreatment, Safety, Guardianship, and Ethical Risk", "description": "This section prepares students for one of the field's hardest tasks: responding to mistreatment and risk while respecting autonomy.", "children": [{"id": "c70108eb-a4f9-41ae-992b-7427a1a1c51b", "type": "subtopic", "title": "Elder abuse, neglect, and exploitation", "children": [{"id": "a49a75d2-5576-4e82-9da9-5a60fee7207e", "type": "concept", "title": "Physical, emotional, sexual abuse and neglect"}, {"id": "699c9831-9fe5-401e-9695-88fa84609e91", "type": "concept", "title": "Financial exploitation and scams"}, {"id": "d2957ec5-9471-459a-a517-43033d188567", "type": "concept", "title": "Self-neglect and environmental risk"}], "description": "Students learn to identify mistreatment while avoiding simplistic assumptions about families, culture, capacity, or dependency."}, {"id": "3831d151-0fe9-44c9-a109-35381845dfbc", "type": "subtopic", "title": "Mandated reporting and safety planning", "children": [{"id": "64d4e19f-c1b1-400d-b78a-834535a5d0a9", "type": "concept", "title": "State reporting pathways"}, {"id": "c6f512a5-f498-407d-b9ba-67d7b4bca1e9", "type": "concept", "title": "Risk assessment and documentation"}, {"id": "3ab60391-09b3-48b9-b3be-bcd8bf9a9c9f", "type": "concept", "title": "Emergency shelter, protective services, and legal referrals"}], "description": "The focus is careful action: meet legal duties, protect safety, and preserve dignity wherever possible."}, {"id": "4a2d76bd-3c85-4c5f-a544-c1794d126ec5", "type": "subtopic", "title": "Guardianship, capacity, and rights", "children": [{"id": "f38cc1a2-1bdd-4154-be38-a98151809178", "type": "concept", "title": "Capacity versus competency"}, {"id": "7dce1272-5671-44db-a089-2be86ee2e884", "type": "concept", "title": "Supported decision-making and least restrictive alternatives"}, {"id": "1795e231-82bb-4bf5-9892-1fb6ecb7cdde", "type": "concept", "title": "Guardianship, conservatorship, and advance planning"}], "description": "Students examine the tension between protection and autonomy in high-stakes decisions."}]}, {"id": "977e4ecb-b023-4214-8be2-d4ee3e7e2ac3", "type": "topic", "title": "End-of-Life Care, Advance Care Planning, Palliative Care, and Bereavement", "description": "This section develops skill in serious-illness, death, dying, and bereavement conversations across cultures and care systems.", "children": [{"id": "215629f4-a353-4f16-a17e-1cad1c837d7a", "type": "subtopic", "title": "Advance care planning", "children": [{"id": "a022df01-1230-44a9-bad1-720b8740000a", "type": "concept", "title": "Health care proxies and advance directives"}, {"id": "4094eac6-3b0f-440a-9d34-5772be59252a", "type": "concept", "title": "Goals-of-care conversations"}, {"id": "802c6e7d-7481-4c39-bd89-4b7fc00cbf95", "type": "concept", "title": "Cultural and family considerations"}], "description": "Students learn to facilitate values-based conversations before crisis, not simply collect forms."}, {"id": "b19bc4c6-c615-47fe-bb94-d3b7f0511e6a", "type": "subtopic", "title": "Palliative and hospice care", "children": [{"id": "2e802c4f-b668-4eed-86d0-624c878cbc92", "type": "concept", "title": "Palliative care across serious illness"}, {"id": "85075ec7-02f6-46cc-9528-f62b3f8ea6ab", "type": "concept", "title": "Hospice eligibility and services"}, {"id": "73585470-7633-47ab-bf4a-908d54fc92f2", "type": "concept", "title": "Pain, suffering, dignity, and spiritual care"}], "description": "This subtopic clarifies how comfort, quality of life, symptom burden, and family support fit social work practice."}, {"id": "19f95e7a-9283-4fa0-9e1b-9823213b62b6", "type": "subtopic", "title": "Bereavement and mourning", "children": [{"id": "43610983-e36c-4a02-be39-dd8670768cfd", "type": "concept", "title": "Anticipatory grief"}, {"id": "10e6d099-93a5-4a1e-a462-035b8bc5aa61", "type": "concept", "title": "Complicated grief and traumatic loss"}, {"id": "613658f8-1501-4693-a8fb-341227a16eb2", "type": "concept", "title": "Ritual, culture, and continuing bonds"}], "description": "Students learn to support caregivers and communities before and after death."}]}, {"id": "b337ff01-86dc-4b9d-8317-2d1bc9c03f18", "type": "topic", "title": "Aging, Diversity, Equity, Culture, and Anti-Oppressive Practice", "description": "This section places equity at the center of gerontological social work, because later-life outcomes reflect decades of unequal opportunity and exposure.", "children": [{"id": "95ba3159-bfb9-4f1d-9386-5e6359d3a517", "type": "subtopic", "title": "Intersectional aging", "children": [{"id": "1498d6d9-4a7a-4ec5-8303-8ae947d39ccd", "type": "concept", "title": "Race, ethnicity, language, class, gender, sexuality, disability, religion"}, {"id": "f436bbfb-eaf6-41b9-9075-1587334c07f6", "type": "concept", "title": "Immigration, refugee status, and documentation"}, {"id": "5b75d579-5e60-4c1b-88d3-5d5679f56357", "type": "concept", "title": "Rural, tribal, and place-based aging"}], "description": "Students learn to understand aging through multiple identities and unequal life chances."}, {"id": "7a0c905a-a614-4878-bf18-c07e25d95a68", "type": "subtopic", "title": "Health disparities and structural inequity", "children": [{"id": "43fd68ae-0461-4b3f-8fc7-4977033b1ee9", "type": "concept", "title": "Racism and weathering"}, {"id": "72fcad2d-cfdf-4fc7-9f15-41e1122632d3", "type": "concept", "title": "Disability justice and accessibility"}, {"id": "ed4efcea-40be-484b-b78b-886f9c66b1bc", "type": "concept", "title": "Housing, food, transportation, and digital inequity"}], "description": "This subtopic connects client-level assessment to upstream conditions that shape aging outcomes."}, {"id": "3c76208c-01e3-4202-9477-2f3b0d54550c", "type": "subtopic", "title": "Culturally responsive and anti-oppressive practice", "children": [{"id": "c3359a38-0bd3-4268-b768-f735090164e7", "type": "concept", "title": "Cultural formulation and explanatory models"}, {"id": "c503db88-81e3-4ca9-bd94-8a599291b6c5", "type": "concept", "title": "Language access and interpreter use"}, {"id": "6dcf4430-5485-4748-a9d3-2ac76252538f", "type": "concept", "title": "Power, bias, and reflective supervision"}], "description": "Students practice humility, accountability, and partnership instead of one-size-fits-all cultural checklists."}]}, {"id": "b7da88ae-38f9-40af-84d2-6ad5121ae20f", "type": "topic", "title": "Aging Policy, Medicare, Medicaid, Social Security, Housing, and Advocacy", "description": "This section gives students the policy and benefits literacy needed to advocate effectively with and for older adults.", "children": [{"id": "ff6e2441-2965-42eb-b87c-617b9424ce31", "type": "subtopic", "title": "Income security and retirement policy", "children": [{"id": "88d7b66e-9d61-4aa9-a6c3-c3cacde2c259", "type": "concept", "title": "Social Security, SSI, pensions, and savings"}, {"id": "b66079d1-38c9-4e03-a089-d004a7b1b12f", "type": "concept", "title": "Older adult poverty and debt"}, {"id": "b109820a-2f83-4f1e-bccd-0df73703f12d", "type": "concept", "title": "Employment, age discrimination, and retirement timing"}], "description": "Students learn how Social Security, pensions, work histories, and poverty affect client choices."}, {"id": "879ef157-de4b-4cbf-a6c6-d18cf8b1c674", "type": "subtopic", "title": "Health and long-term care financing", "children": [{"id": "0c9898c8-7fae-4c1a-923f-09e078c1534c", "type": "concept", "title": "Medicare Parts A, B, C, and D"}, {"id": "cebf30d3-0a07-49f6-bdff-b0ff0266760a", "type": "concept", "title": "Medicaid eligibility and long-term services"}, {"id": "5e065df0-faea-4f73-a986-2c8858a42e3f", "type": "concept", "title": "Dual eligibility and spend-down issues"}], "description": "This subtopic makes Medicare, Medicaid, private insurance, and out-of-pocket costs understandable for practice."}, {"id": "f4d9200e-969b-48c3-9e3c-e21810dee949", "type": "subtopic", "title": "Housing, civil rights, and advocacy", "children": [{"id": "ff440a7e-3d3d-4e8e-93d2-3cb1434eceaa", "type": "concept", "title": "Older Americans Act and aging services"}, {"id": "14f5130a-f9e1-4939-90a5-a2d8f2970ca5", "type": "concept", "title": "Affordable housing and homelessness prevention"}, {"id": "cb030d86-5d02-43d6-a11e-b7b31b47f735", "type": "concept", "title": "Legislative advocacy and coalition work"}], "description": "Students learn to move from individual resource referral to policy advocacy."}]}, {"id": "c307b903-9717-4bc2-926c-d8e6f855cfbd", "type": "topic", "title": "Community-Based Aging Networks, Benefits Access, and Resource Navigation", "description": "This section makes the aging-services ecosystem practical, navigable, and programmatically useful.", "children": [{"id": "e85fa7a8-7f5f-4033-8140-c755a0ae5e0e", "type": "subtopic", "title": "Aging network structure", "children": [{"id": "8782b473-c50c-4b6b-830b-8bfe814c59b7", "type": "concept", "title": "Area Agencies on Aging"}, {"id": "465ec77d-9ded-4151-ba9a-450714d34ede", "type": "concept", "title": "Aging and Disability Resource Centers"}, {"id": "21dbaece-23d4-4b8e-8cf0-1603dac32e59", "type": "concept", "title": "Senior centers, ombuds programs, and community partners"}], "description": "Students learn the service ecosystem so they can navigate it confidently with clients."}, {"id": "bb63599a-0a31-4474-aa41-de7fd5eff943", "type": "subtopic", "title": "Benefits and resource navigation", "children": [{"id": "dc9da7f3-08e3-4d7f-983e-754a8a4e9596", "type": "concept", "title": "SNAP, LIHEAP, Medicare Savings Programs, and prescription help"}, {"id": "558b5222-f7df-4176-b1cd-5e5ac83ae453", "type": "concept", "title": "Transportation, meals, legal aid, and caregiver supports"}, {"id": "60788aba-ff88-4143-b50b-c3d98f0b752c", "type": "concept", "title": "Documentation and eligibility barriers"}], "description": "This subtopic teaches practical screening, referral, and follow-through skills."}, {"id": "ce97d523-8d70-4fbe-aef4-606d0dc10eb4", "type": "subtopic", "title": "Community practice and program development", "children": [{"id": "ee570e0a-6ea8-4e78-853e-4a0d9991d36a", "type": "concept", "title": "Needs assessment and asset mapping"}, {"id": "57c401b5-1161-463e-8af2-e4dfb79a750b", "type": "concept", "title": "Partnerships and outreach"}, {"id": "0f56ef16-0dd1-4395-911a-8ec63e0561ac", "type": "concept", "title": "Program evaluation and continuous improvement"}], "description": "Students learn to design responsive programs with older adults rather than for them."}]}, {"id": "45e2aa58-d512-4954-9c21-8b8e8d6f9c9c", "type": "topic", "title": "Technology, Telehealth, Accessibility, and Innovation in Aging Services", "description": "This section asks students to evaluate technology as a tool for autonomy and access, but also as a source of exclusion, surveillance, and bias.", "children": [{"id": "35292a9c-c012-4b49-90a0-3d18896ca704", "type": "subtopic", "title": "Telehealth and digital inclusion", "children": [{"id": "a76f5b4f-5bcb-4e71-9c4b-499cc5970a92", "type": "concept", "title": "Telehealth etiquette and privacy"}, {"id": "443cdb54-6439-421d-b6f2-e8979786fed6", "type": "concept", "title": "Broadband, device access, and digital literacy"}, {"id": "e9a22ceb-3a21-4e62-8153-e5b2dcbd107e", "type": "concept", "title": "Accessibility and language supports"}], "description": "Students examine how technology can expand access while also excluding people without devices, broadband, literacy, or trust."}, {"id": "db04e605-14ff-45b9-984f-df3f38c1c91e", "type": "subtopic", "title": "Assistive and smart-home technologies", "children": [{"id": "2e272e81-23d3-4cd7-b381-57e2b4bdc18f", "type": "concept", "title": "Medication reminders, fall detection, and sensors"}, {"id": "398d1a7a-8359-4045-890b-007eda22357a", "type": "concept", "title": "Mobility, vision, hearing, and communication aids"}, {"id": "96488fb1-5fd1-41ed-908c-0c485d3ab196", "type": "concept", "title": "Ethical concerns about monitoring and consent"}], "description": "This subtopic helps students evaluate tools that support autonomy, safety, and caregiver communication."}, {"id": "f2c11e7a-ba6f-4adb-8b04-971f9a59264a", "type": "subtopic", "title": "Innovation and risk", "children": [{"id": "88c4c95e-f9fd-4e7c-85c0-5fb4590c3369", "type": "concept", "title": "AI triage and bias"}, {"id": "24834568-3710-44e6-a886-5f60395dc87d", "type": "concept", "title": "Data privacy and surveillance"}, {"id": "6fde89db-9177-4f3d-80aa-0b6fe336a806", "type": "concept", "title": "Implementation, training, and evaluation"}], "description": "Students learn to ask whether new tools are effective, equitable, secure, and compatible with social-work values."}]}, {"id": "ec19ff94-85bf-4e7f-a37c-9795fab7b430", "type": "topic", "title": "Professional Ethics, Documentation, Self-Care, and Field Integration", "description": "This final section integrates professional identity, ethics, documentation, supervision, self-care, and field-based application.", "children": [{"id": "bf52a990-7f58-4280-997d-4dc3f302c397", "type": "subtopic", "title": "Professional ethics in gerontological practice", "children": [{"id": "eeadab75-d5d7-436b-8cdd-308ae7327a32", "type": "concept", "title": "NASW Code of Ethics applications"}, {"id": "5c3908be-f249-4f84-8d04-4b87f6f63109", "type": "concept", "title": "Dual relationships and family pressure"}, {"id": "47d11a36-59e8-4a43-9758-2157ed5f2564", "type": "concept", "title": "Confidentiality with caregivers and teams"}], "description": "Students integrate autonomy, dignity, confidentiality, informed consent, boundaries, and social justice in complex aging cases."}, {"id": "6c75bb37-f69c-4999-8eef-77c97e9b0105", "type": "subtopic", "title": "Documentation and supervision", "children": [{"id": "647dac1f-ed88-4000-9d23-ce207d609d19", "type": "concept", "title": "Assessment notes and service plans"}, {"id": "b22b100b-0fc4-4fb8-bf30-775b26e60cc0", "type": "concept", "title": "Risk documentation"}, {"id": "16b0a07e-7894-42a7-a4b1-45db871f4add", "type": "concept", "title": "Supervision, consultation, and interprofessional records"}], "description": "This subtopic builds the habit of clear, defensible, strengths-based records and reflective consultation."}, {"id": "f35389fe-35d8-4fda-b1e7-22ea34211af8", "type": "subtopic", "title": "Field integration and practitioner sustainability", "children": [{"id": "5e3e209c-5212-4752-91af-bcbd71b3c75a", "type": "concept", "title": "Use of self and reflective practice"}, {"id": "a2857e08-b9ec-4bf3-97d7-77bb89642309", "type": "concept", "title": "Secondary trauma and grief exposure"}, {"id": "18947087-c987-4d9f-8bf2-5251ed338939", "type": "concept", "title": "Capstone presentation and professional development plan"}], "description": "Students connect classroom knowledge to field learning while protecting against burnout and moral distress."}]}], "dbBacked": true}$agswjson$::jsonb,
